/**
 * Create a supplier without leaving the PO form. Vendor code is generated by the API (VEN-0001...).
 * Full details (bank, compliance, ledger) can be completed later on the Vendors page.
 */
import { useEffect, useState } from "react";
import { X } from "lucide-react";
import { api, type VendorResponse } from "@/api/client";
import { Button } from "@/components/ui/button";
import { logApiError } from "@/utils/logApiError";

const CTL = "w-full rounded-lg border border-border-strong bg-surface-raised px-3 py-2 text-sm";

export function VendorQuickCreateModal({
  open,
  initialName,
  defaultCurrency,
  onClose,
  onCreated,
}: {
  open: boolean;
  initialName?: string;
  defaultCurrency?: string;
  onClose: () => void;
  onCreated: (vendor: VendorResponse) => void;
}) {
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [currency, setCurrency] = useState("USD");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!open) return;
    setName(initialName ?? "");
    setPhone("");
    setEmail("");
    setCurrency((defaultCurrency || "USD").toUpperCase());
    setError("");
  }, [open, initialName, defaultCurrency]);

  if (!open) return null;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    e.stopPropagation();
    if (!name.trim()) return setError("Enter a supplier name.");
    setBusy(true);
    setError("");
    try {
      const created = await api.createVendor({
        name: name.trim(),
        phone: phone.trim() || null,
        email: email.trim() || null,
        default_currency: currency.trim().toUpperCase() || null,
        is_active: true,
      });
      onCreated(created);
      onClose();
    } catch (err) {
      logApiError("VendorQuickCreateModal.create", err);
      setError(err instanceof Error ? err.message : "Could not create supplier.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby="vendor-quick-create-title"
    >
      <form
        className="w-full max-w-md space-y-3 rounded-xl border border-border bg-surface-raised p-5 shadow-xl"
        onClick={(e) => e.stopPropagation()}
        onSubmit={handleSubmit}
        onKeyDown={(e) => {
          if (e.key === "Escape") onClose();
        }}
      >
        <div className="flex items-center justify-between">
          <h2 id="vendor-quick-create-title" className="text-base font-semibold text-text-primary">
            New supplier
          </h2>
          <button type="button" onClick={onClose} aria-label="Close" className="rounded-md p-1 text-text-muted hover:bg-surface-subtle">
            <X className="h-4 w-4" />
          </button>
        </div>
        {error ? (
          <div className="rounded-md border border-status-danger/30 bg-status-danger-subtle px-3 py-2 text-sm text-status-danger-foreground">{error}</div>
        ) : null}
        <div>
          <label className="mb-1 block text-xs font-medium text-text-secondary">Supplier name</label>
          <input className={CTL} value={name} onChange={(e) => setName(e.target.value)} autoFocus required />
        </div>
        <div className="grid grid-cols-2 gap-2">
          <div>
            <label className="mb-1 block text-xs font-medium text-text-secondary">Phone</label>
            <input className={CTL} value={phone} onChange={(e) => setPhone(e.target.value)} />
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-text-secondary">Currency</label>
            <input className={CTL} value={currency} maxLength={3} onChange={(e) => setCurrency(e.target.value.toUpperCase())} />
          </div>
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-text-secondary">Email</label>
          <input className={CTL} type="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        </div>
        <p className="text-xs text-text-muted">A supplier code is generated automatically. Add bank and compliance details later on the Vendors page.</p>
        <div className="flex justify-end gap-2 pt-1">
          <Button type="button" variant="outline" onClick={onClose} disabled={busy}>
            Cancel
          </Button>
          <Button type="submit" disabled={busy}>
            {busy ? "Saving…" : "Create supplier"}
          </Button>
        </div>
      </form>
    </div>
  );
}
